import { describe, expect, it } from 'bun:test';
import fs from 'node:fs';

import { listFixtures, mapFixture } from '../../scripts/fixtures.ts';

// Each fixture is a real session recorded from the vendor's CLI. Its expectation changes only
// with a deliberate manifest or mapper change, regenerated by `bun scripts/fixtures.ts`.
describe('official manifests map recorded sessions', () => {
  for (const fixture of listFixtures()) {
    it(`${fixture.manifestId}: ${fixture.name}`, () => {
      const expected: unknown = JSON.parse(fs.readFileSync(fixture.expectedPath, 'utf8'));
      expect(mapFixture(fixture)).toEqual(expected as ReturnType<typeof mapFixture>);
    });
  }
});
